UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Phlegmasia Cerulea Dolens — Threatened-Limb Gate","body":"**Phlegmasia cerulea dolens is a massive iliofemoral DVT that obstructs venous outflow — the limb becomes tensely swollen, painful, and dusky/cyanotic, and venous gangrene and limb loss follow.** It is a limb-threatening emergency distinct from an ordinary DVT. Look for the whole-leg tense swelling, cyanotic mottling, and severe pain; a compromised limb may lose pulses secondarily from the massive edema. Often associated with malignancy or a prothrombotic state.","citation":[3],"options":[{"label":"Whole-leg tense cyanotic swelling + severe pain","description":"Treat as phlegmasia — limb emergency","next":"uls-phlegmasia-verdict","urgency":"critical"},{"label":"Focal swelling, no cyanosis, limb not threatened","description":"Not phlegmasia — assess for ordinary DVT","next":"uls-phlegmasia-excluded","urgency":"routine"}],"images":[{"src":"images/phlegmasia/cerulea-heilman.jpg","alt":"Clinical photograph of phlegmasia cerulea dolens: one leg is markedly swollen and purple compared with the opposite leg.","caption":"Phlegmasia cerulea dolens. James Heilman, MD, 2016. CC BY-SA 4.0. Original photograph, unmodified."}],"calculatorLinks":[{"id":"phlegmasia-photos","label":"Cerulea / Alba Photos","kind":"info"}],"summary":"Tense cyanotic whole-leg swelling + pain = phlegmasia (massive iliofemoral DVT); venous gangrene / limb loss without decompression.","safetyLevel":"critical"}'::jsonb
